/*
 * prog24_query_string_parser.c
 *
 * Re‑implementation of the original program (the observable behaviour only).
 * The program reads one line from stdin, interprets it as a URL‑encoded query
 * string (key=value pairs separated by '&'), decodes each key and value and
 * prints them one per line as:
 *
 *      key=value
 *
 * If no line can be read (fgets returns NULL) the program prints the literal
 * string "NO_INPUT" and exits.
 *
 * The decoding follows the usual URL‑encoding rules:
 *   - '+' is translated to a space character.
 *   - "%XY" where X and Y are hexadecimal digits is translated to the byte
 *     with value 0xXY.
 *   - Any other character is copied unchanged.
 *
 * The implementation is deliberately straightforward – the original binary
 * used an obfuscated state‑machine, but the functional behaviour is exactly
 * the same as the code below.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 2048          /* matches the original 0x800 buffer */
#define MAX_TOKEN 1024         /* buffers for a single key or value */

/* --------------------------------------------------------------------- */
/* URL‑decode a null‑terminated string.
 *
 *  src  – input string (may contain %XX escapes and '+')
 *  dst  – buffer where the decoded string is written; must be large enough.
 *
 * The function returns dst for convenience.
 */
static char *url_decode(const char *src, char *dst)
{
    const unsigned char *p = (const unsigned char *)src;
    unsigned char *q = (unsigned char *)dst;

    while (*p) {
        if (*p == '+') {
            *q++ = ' ';
            p++;
        } else if (*p == '%' && isxdigit(p[1]) && isxdigit(p[2])) {
            unsigned int hi = (unsigned int)(isdigit(p[1]) ? p[1] - '0'
                                 : (toupper(p[1]) - 'A' + 10));
            unsigned int lo = (unsigned int)(isdigit(p[2]) ? p[2] - '0'
                                 : (toupper(p[2]) - 'A' + 10));
            *q++ = (unsigned char)((hi << 4) | lo);
            p += 3;
        } else {
            *q++ = *p++;
        }
    }
    *q = '\0';
    return dst;
}

/* --------------------------------------------------------------------- */
int main(void)
{
    static char line[MAX_LINE];
    static char key_raw[MAX_TOKEN];
    static char val_raw[MAX_TOKEN];
    static char key_dec[MAX_TOKEN];
    static char val_dec[MAX_TOKEN];

    /* Read a line from stdin.  The original program used a buffer of 0x800
       bytes, so we keep the same limit. */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing newline and optional carriage‑return (the original
       code handled both '\n' and '\r'). */
    size_t len = strlen(line);
    if (len && line[len - 1] == '\n') {
        line[--len] = '\0';
        if (len && line[len - 1] == '\r')
            line[--len] = '\0';
    }

    /* Parse the query string: key=value pairs separated by '&'. */
    char *p = line;
    while (*p) {
        /* Locate the end of the current token (next '&' or end of string). */
        char *token_end = strchr(p, '&');
        if (!token_end)
            token_end = p + strlen(p);   /* point to terminating '\0' */

        /* Within the token, find the first '=' (if any). */
        char *eq = memchr(p, '=', (size_t)(token_end - p));

        if (eq) {
            /* key = characters before '=', value = after '=' up to token_end */
            size_t key_len = (size_t)(eq - p);
            size_t val_len = (size_t)(token_end - eq - 1);

            if (key_len >= sizeof(key_raw))
                key_len = sizeof(key_raw) - 1;
            if (val_len >= sizeof(val_raw))
                val_len = sizeof(val_raw) - 1;

            memcpy(key_raw, p, key_len);
            key_raw[key_len] = '\0';
            memcpy(val_raw, eq + 1, val_len);
            val_raw[val_len] = '\0';
        } else {
            /* No '=', the whole token is the key and the value is empty. */
            size_t key_len = (size_t)(token_end - p);
            if (key_len >= sizeof(key_raw))
                key_len = sizeof(key_raw) - 1;
            memcpy(key_raw, p, key_len);
            key_raw[key_len] = '\0';
            val_raw[0] = '\0';
        }

        /* Decode both parts. */
        url_decode(key_raw, key_dec);
        url_decode(val_raw, val_dec);

        /* Print the pair. */
        printf("%s=%s\n", key_dec, val_dec);

        /* Advance to the next token (skip the '&' if present). */
        if (*token_end == '&')
            p = token_end + 1;
        else
            break;          /* reached the end of the line */
    }

    return 0;
}
